// Saved-library regression using generated bytes; all remote traffic is blocked.
import assert from 'node:assert/strict';
import { once } from 'node:events';
import puppeteer from 'puppeteer-core';
import { createServer } from '../scripts/server.mjs';

const server = createServer({fetchArchive: async () => { throw Error('Unexpected relay request'); }});
server.listen(0, '127.0.0.1'); await once(server, 'listening');
const base = `http://127.0.0.1:${server.address().port}`;
let browser;
try {
  browser = await puppeteer.launch({executablePath: process.env.CHROME_PATH || '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true, args: ['--no-sandbox']});
  const page = await browser.newPage(), errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.setRequestInterception(true);
  page.on('request', request => {
    if (!request.url().startsWith(base + '/')) return request.abort('failed');
    request.continue();
  });
  await page.goto(base, {waitUntil: 'networkidle0'});
  await page.waitForFunction(() => !document.querySelector('#validate').disabled);
  await page.waitForFunction(() => document.querySelector('#library-status').textContent.includes('No saved games yet'));
  assert.equal(await page.$eval('a[href="#shared-library"]', el => el.textContent), 'Browse shared library');

  await page.evaluate(() => {
    window.loadUpdates = [];
    new MutationObserver(() => window.loadUpdates.push({
      label: document.querySelector('#loadbar-label').textContent,
      progress: document.querySelector('#loadbar').getAttribute('aria-valuenow')
    })).observe(document.querySelector('#loadbar-panel'), {subtree: true, childList: true, attributes: true});
  });

  // Exercise the actual file picker import and streaming save, with no BIOS/game data.
  await page.evaluate(() => {
    const bytes = new Uint8Array(65536); bytes.set([0x7f, 0x45, 0x4c, 0x46]);
    const transfer = new DataTransfer(); transfer.items.add(new File([bytes], 'Generated Alpha.elf'));
    const input = document.querySelector('#disc'); input.files = transfer.files; input.dispatchEvent(new Event('change'));
  });
  await page.waitForFunction(() => document.querySelector('#library li button')?.textContent.includes('Generated Alpha.elf'));
  assert.equal(await page.evaluate(() => window.loadUpdates.some(update => update.label === 'Saving to library…' && update.progress === '100')), true);
  await page.evaluate(async () => {
    const {cacheFile} = await import('./storage.js');
    await cacheFile(new File([new Uint8Array([1, 2, 3])], 'Generated Beta.iso'), 'disc');
  });
  await page.reload({waitUntil: 'networkidle0'});
  await page.waitForFunction(() => document.querySelectorAll('#library li').length === 2);
  assert.match(await page.$eval('#library-status', el => el.textContent), /2 of 2 saved games/);
  await page.type('#library-search', 'aLpHa');
  await page.waitForFunction(() => document.querySelectorAll('#library li').length === 1);
  assert.match(await page.$eval('#library li button', el => el.textContent), /Generated Alpha/);
  await page.click('#library li button');
  await page.waitForFunction(() => document.querySelector('#selected').textContent.includes('Generated Alpha'));
  assert.equal(await page.$eval('#btn-load-game', el => el.disabled), false);
  assert.equal(await page.$eval('#loadbar-panel', el => el.hidden), true);
  // Verify replay reached the Wasm mount without transferring the file a second time.
  assert.match(await page.$eval('#status', el => el.textContent), /Game mounted. Header and end-of-file reads verified/);

  await page.$eval('#library-search', el => { el.value = 'missing'; el.dispatchEvent(new Event('input')); });
  await page.waitForFunction(() => document.querySelector('#library-status').textContent.includes('No saved games match'));
  assert.equal(await page.$$eval('#library li', rows => rows.length), 0);
  await page.$eval('#library-search', el => { el.value = ''; el.dispatchEvent(new Event('input')); });
  await page.waitForFunction(() => document.querySelectorAll('#library li').length === 2);
  await page.click('#library li button[aria-label^="Remove"]');
  await page.waitForFunction(() => document.querySelectorAll('#library li').length === 1);
  await page.reload({waitUntil: 'networkidle0'});
  await page.waitForFunction(() => document.querySelectorAll('#library li').length === 1);
  assert.deepEqual(errors, []);
  console.log('PASS: generated streamed import, saved-library replay after reload, case-insensitive search, empty results, removal persistence. No remote downloads.');
} finally {
  await browser?.close(); server.closeAllConnections(); await new Promise(resolve => server.close(resolve));
}
